#!/bin/bash
# Keep host/build settings without copying Actions metadata into Wasm guests.
set -euo pipefail

if (( $# == 0 )); then
  printf 'usage: logos-test-env.sh command [argument ...]\n' >&2
  exit 2
fi

keys=(
  HOME USER LOGNAME PATH TMPDIR LANG LC_ALL LC_CTYPE TZ
  GOROOT GOROOT_BOOTSTRAP GOPATH GOCACHE GOMODCACHE GOTMPDIR GOCOVERDIR
  GOENV GOWORK GO111MODULE GOTOOLCHAIN GOTELEMETRY
  GOFIPS140 GOPROXY GOSUMDB GOPRIVATE GONOPROXY GONOSUMDB GOINSECURE GOVCS GOAUTH
  GOOS GOARCH GOHOSTOS GOHOSTARCH GOAMD64 GO386 GOARM GOARM64
  GOMIPS GOMIPS64 GOPPC64 GORISCV64 GOWASM
  GOEXPERIMENT GODEBUG GOFLAGS GO_GCFLAGS GO_LDFLAGS GO_TEST_ASMFLAGS
  GO_TEST_SHORT GO_TEST_SHARDS GO_TEST_TIMEOUT_SCALE GO_BUILDER_NAME
  GOTRACEBACK GOMAXPROCS GOMEMLIMIT GOGC GORACE
  CGO_ENABLED CC CXX FC AR PKG_CONFIG
  CGO_CFLAGS CGO_CPPFLAGS CGO_CXXFLAGS CGO_FFLAGS CGO_LDFLAGS
  CGO_CFLAGS_ALLOW CGO_CFLAGS_DISALLOW CGO_CPPFLAGS_ALLOW CGO_CPPFLAGS_DISALLOW
  CGO_CXXFLAGS_ALLOW CGO_CXXFLAGS_DISALLOW CGO_FFLAGS_ALLOW CGO_FFLAGS_DISALLOW
  CGO_LDFLAGS_ALLOW CGO_LDFLAGS_DISALLOW
  CFLAGS CPPFLAGS CXXFLAGS LDFLAGS LD_LIBRARY_PATH LIBRARY_PATH
  CPATH C_INCLUDE_PATH CPLUS_INCLUDE_PATH
  GCCGO GCCGOTOOLDIR GO_TESTING_GOTOOLS UPROOT1272 UPROOT1273 UPROOT1274
)

compact=()
for key in "${keys[@]}"; do
  if [[ -v $key && ${!key@a} == *x* ]]; then
    compact+=("$key=${!key}")
  fi
done

exec /usr/bin/env -i "${compact[@]}" "$@"
